// SPDX-License-Identifier: GPL-3.0-or-later
//
// Lightloom plugin data: Corsair peripherals (OpenRGB's CorsairPeripheralController family):
// product table and key layouts. Generated from the OpenRGB tables; do not edit by hand.
// Adapted from OpenRGB Controllers/CorsairPeripheralController/CorsairPeripheralControllerDetect.cpp
// (product ids, names, detector macros), CorsairPeripheralController.cpp (keys, keys_k70_mk2,
// keys_k95_plat, keys_k95, st100, key_mapping_k95_plat_ansi / _iso, key_mapping_k70_mk2_plat_iso),
// RGBController_CorsairPeripheral.cpp (matrix maps, LED names), CorsairK55RGBPROXTController.cpp
// (keys), RGBController_CorsairK55RGBPROXT.cpp (matrix_map, key_names),
// RGBController_CorsairK65Mini.cpp (matrix_map, keys) and RGBController/RGBControllerKeyNames.cpp
// (key name strings) (GPL-2.0-or-later) at commit d4798c120659ec5ba2e664a9e87bedff8d36f880,
// https://gitlab.com/CalcProgrammer1/OpenRGB
// Original authors: "Adam Honse (CalcProgrammer1)  09 Jan 2020" (CorsairPeripheralController,
// RGBController_CorsairPeripheral); "Chris M (Dr_No)  25 Jan 2022" (RGBControllerKeyNames); the
// detector, K55 RGB PRO XT and K65 Mini files name no author ("This file is part of the OpenRGB
// project").
//
// Keyboard layouts: leds are [name, column, row] in OpenRGB's LED order (the order colours go
// into the packets); the cells come from OpenRGB's matrix maps. Lightloom additions, so every LED
// has a cell: NORMAL puts Brightness, Windows Lock and Media Mute (not in OpenRGB's 6 x 23 map)
// on a top row where the K70 LUX RGB map has them; K70_LUX_RGB puts Profile, Logo Left and Logo
// Right where the K70 MK.2 map has them; K95_PLAT gets its 19-LED Light Bar zone as a top row.
// keys[i] is the slot of LED i in the 24-bit colour buffers (SetLEDsKeyboardFull); dataSize is
// the length of the third stream packet (24, or 48 on the K95 layouts).

export const VENDOR_ID = 0x1B1C;

